// Which of the channel's newest videos are not in the sheet yet? One item carrying the list, so the summariser runs once.
const done = new Set($input.all().map((i) => i.json.videoId).filter(Boolean));
const listed = $("List the channel's newest videos").all().map((i) => i.json).filter((r) => r.videoId || r.url);
const fresh = listed.filter((r) => !done.has(r.videoId)).map((r) => r.url || ('https://www.youtube.com/watch?v=' + r.videoId));
return fresh.length ? [{ json: { videoUrls: fresh, count: fresh.length } }] : [];

// One row per video: what it is, how it did, and the summary in your language.
const today = new Date().toISOString().slice(0, 10);
return $input.all().map((i) => i.json).filter((r) => r.videoId).map((r) => ({ json: {
  summarisedOn: today, title: r.title, channel: r.author, url: r.url, videoId: r.videoId, publishedAt: r.publishedAt, views: r.views,
  minutes: r.durationSec ? Math.round(r.durationSec / 60) : '', spokenLanguage: r.detectedLanguage, summary: r.output || r.summary || '', note: r.note || '',
} }));
